import { useEffect, useRef, useState } from 'react';
import { freshBoardCode } from '../session/fresh-board.ts';
import { Bracket } from './Bracket.tsx';
import { LeaveDialog } from './LeaveDialog.tsx';
import { Turn } from './Turn.tsx';
import type { TurnHandle } from './Turn.tsx';
import { createTournament, normalizeNames, recordScore, roundName, roundSize } from './rules.ts';
import type { Score, TournamentData } from './rules.ts';
import { exportTournament, readTournament } from './format.ts';
import { readHistory, saveHistory } from './storage.ts';
import './tournament.css';

const EMPTY = JSON.stringify(
  { format: 'neon-pairs/tournament', tournament: null, version: 1 },
  null,
  2,
);
export function Tournament({ back }: { back(): void }) {
  const [historyState] = useState(readHistory);
  const [history, setHistory] = useState(historyState.items);
  const [blocked, setBlocked] = useState(historyState.blocked);
  const [t, setT] = useState<TournamentData | null>(null);
  const [count, setCount] = useState(4);
  const [drafts, setDrafts] = useState<string[]>(Array(8).fill(''));
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState(0);
  const heading = useRef<HTMLHeadingElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const turn = useRef<TurnHandle>(null);
  const pending = useRef<() => void>(() => {});
  function announce(text: string) {
    setNotice(text);
    setAnnouncement((n) => n + 1);
  }
  useEffect(() => {
    heading.current?.focus();
  }, [t === null ? 'setup' : t.phase]);
  function confirm(action: () => void) {
    if (t && t.phase !== 'complete') {
      pending.current = action;
      dialog.current?.showModal();
    } else action();
  }
  function start() {
    const result = normalizeNames(drafts.slice(0, count));
    if (result.error) {
      announce(result.error);
      return;
    }
    const codes: string[] = [];
    for (let i = 0; i < count - 1; i++) {
      let code: string;
      do {
        code = freshBoardCode(roundSize(count, i));
      } while (codes.includes(code));
      codes.push(code);
    }
    setT(createTournament(result.names, codes));
    announce(`Now playing: ${result.names[0]}`);
  }
  function finish(score: Score) {
    if (!t || t.phase !== 'playing') return;
    const next = recordScore(t, score);
    setT(next);
    if (next.phase === 'complete') {
      const items = [next, ...history].slice(0, 10);
      setHistory(items);
      if (!saveHistory(items)) setBlocked(true);
      announce(`Champion: ${next.players[next.matches[next.index]!.winner!]}`);
    } else if (next.phase === 'matchDone')
      announce(`Winner: ${next.players[next.matches[next.index]!.winner!]}`);
    else announce('Turn complete.');
  }
  function load() {
    if (json.trim() === EMPTY) {
      confirm(() => {
        setT(null);
        announce('Tournament loaded.');
      });
      return;
    }
    const result = readTournament(json);
    if (!result.data) {
      announce(result.error);
      return;
    }
    const data = result.data;
    confirm(() => {
      setT(data);
      announce('Tournament loaded.');
    });
  }
  const match = t?.matches[t.index];
  const player = t && match ? t.players[match.players[match.scores[0] ? 1 : 0]!] : '';
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
      </header>
      <h2 tabIndex={-1} ref={heading}>
        {t?.phase === 'complete' ? 'Tournament results' : 'Tournament'}
      </h2>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={announcement}>{notice}</span>
        </p>
      </div>
      {!t && (
        <>
          <label htmlFor="players">Players</label>{' '}
          <select
            id="players"
            className="control"
            value={count}
            onChange={(e) => setCount(Number(e.currentTarget.value))}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
          <div className="player-fields">
            {drafts.slice(0, count).map((draft, i) => (
              <div key={i}>
                <label htmlFor={`player-${i}`}>Player {i + 1}</label>
                <input
                  className="control"
                  id={`player-${i}`}
                  value={draft}
                  onChange={(e) => {
                    const copy = [...drafts];
                    copy[i] = e.currentTarget.value;
                    setDrafts(copy);
                  }}
                />
              </div>
            ))}
          </div>
          <div className="tournament-actions">
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
            <button className="control" type="button" onClick={back}>
              Back to game
            </button>
          </div>
          <h3>Past tournaments</h3>
          {blocked && <p>Progress won't be saved on this device.</p>}
          {history.length === 0 ? (
            <p>No past tournaments yet.</p>
          ) : (
            <ul>
              {history.map((item, i) => (
                <li key={i}>
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setT(item);
                      announce('Tournament loaded.');
                    }}
                  >
                    Champion: {item.players[item.matches[item.index]!.winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </>
      )}
      {t && match && (
        <>
          {t.phase === 'complete' ? (
            <p className="champion">Champion: {t.players[match.winner!]}</p>
          ) : (
            <>
              <p>Round: {roundName(t.players.length, t.index)}</p>
              <p>Now playing: {player}</p>
            </>
          )}
          <div className="tournament-actions">
            {t.phase === 'ready' && (
              <button
                className="control"
                type="button"
                onClick={() => {
                  setT({ ...t, phase: 'playing' });
                  announce(`Now playing: ${player}`);
                }}
              >
                Start turn
              </button>
            )}
            {t.phase === 'turnDone' && (
              <button
                className="control"
                type="button"
                onClick={() => {
                  setT({ ...t, phase: 'ready' });
                  announce(`Now playing: ${t.players[match.players[1]!]}`);
                }}
              >
                Next turn
              </button>
            )}
            {t.phase === 'matchDone' && (
              <button
                className="control"
                type="button"
                onClick={() => {
                  const next = t.matches[t.index + 1]!;
                  setT({ ...t, index: t.index + 1, phase: 'ready' });
                  announce(`Now playing: ${t.players[next.players[0]!]}`);
                }}
              >
                Next match
              </button>
            )}
            {t.phase === 'complete' ? (
              <>
                <button className="control" type="button" onClick={back}>
                  Back to game
                </button>
                <button className="control" type="button" onClick={() => setT(null)}>
                  Tournament screen
                </button>
              </>
            ) : (
              <button className="control" type="button" onClick={() => confirm(back)}>
                Leave tournament
              </button>
            )}
          </div>
          {t.phase === 'playing' && (
            <Turn
              ref={turn}
              key={`${t.index}-${match.scores[0] ? 1 : 0}`}
              code={match.boardCode}
              snapshot={t.snapshot}
              finish={finish}
              feedback={announce}
            />
          )}
          <Bracket tournament={t} />
        </>
      )}
      <section className="tournament-exchange">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          value={json}
          onChange={(e) => setJson(e.currentTarget.value)}
          maxLength={65536}
          rows={6}
        />
        <div className="tournament-actions">
          <button
            className="control"
            type="button"
            onClick={() => {
              setJson(
                t
                  ? exportTournament({
                      ...t,
                      snapshot: t.phase === 'playing' ? (turn.current?.snapshot() ?? null) : null,
                    })
                  : EMPTY,
              );
              announce('Tournament exported.');
            }}
          >
            Export tournament
          </button>
          <button className="control" type="button" onClick={load}>
            Load tournament
          </button>
        </div>
      </section>
      <LeaveDialog ref={dialog} leave={() => pending.current()} />
    </main>
  );
}

