import assert from 'node:assert/strict';
import { before, after, test as nodeTest } from 'node:test';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { chromium, expect as playwrightExpect } from '@playwright/test';
import { spawnSync } from 'node:child_process';
import { REFERENCE_ROOT, serveArtifact } from './artifact-server.ts';
import type { Browser, BrowserContext, BrowserContextOptions, Page } from '@playwright/test';

const BROWSER_TEMP = join(REFERENCE_ROOT, '.browser-work');
const RESULTS = join(REFERENCE_ROOT, 'test-results');
const CHROMIUM_VERSION = '156.0.8078.4';
const EXECUTABLE_ENV = 'PLAYWRIGHT_CHROMIUM_EXECUTABLE';
// Set to 1 for named-combination evidence. Other supported runtimes run and record their versions.
const NAMED_COMBINATION_ENV = 'NEON_PAIRS_NAMED_COMBINATION';
const NAMED_COMBINATION = {
  node: '26.12.1',
  npm: '11.20.0',
  playwright: '1.64.1',
  chromium: CHROMIUM_VERSION,
};
// Playwright hides scrollbars by default. Visible ones take layout space, as on a Windows desktop.
const HIDE_SCROLLBARS = '--hide-scrollbars';
export const Scrollbars = { hidden: 'hidden', visible: 'visible' } as const;
type ScrollbarMode = (typeof Scrollbars)[keyof typeof Scrollbars];
// A busy verifier runs many browsers at once, so a single wait gets more than Playwright's 5s default.
export const expect = playwrightExpect.configure({ timeout: 15_000 });
// Most journeys fit the standard limit. The accessibility journey and the large boards take the long one.
export const TestTimeouts = { standard: 30_000, long: 90_000 } as const;
// npm names itself and its version to every script it runs, so a browser file needs no npm process of its own.
const NPM_AGENT_ENV = 'npm_config_user_agent';
let browser: Browser | undefined;
let scrollbarBrowser: Promise<Browser> | undefined;
let artifact: Awaited<ReturnType<typeof serveArtifact>> | undefined;

before(async () => {
  await mkdir(BROWSER_TEMP, { recursive: true });
  await mkdir(RESULTS, { recursive: true });
  process.env.TEMP = BROWSER_TEMP;
  process.env.TMP = BROWSER_TEMP;
  const npm = /^npm\/(\S+)/.exec(process.env[NPM_AGENT_ENV] ?? '')?.[1] ?? npmVersion();
  const playwright: unknown = JSON.parse(
    await readFile(new URL(import.meta.resolve('@playwright/test/package.json')), 'utf8'),
  );
  assert.ok(playwright && typeof playwright === 'object' && 'version' in playwright);
  browser = await launch(Scrollbars.hidden);
  const runtime = {
    node: process.versions.node,
    npm,
    playwright: String(playwright.version),
    chromium: browser.version(),
  };
  const named = process.env[NAMED_COMBINATION_ENV] === '1';
  await writeFile(
    join(RESULTS, 'browser-runtime.json'),
    JSON.stringify({ ...runtime, namedCombination: named }, null, 2),
  );
  if (named) assert.deepEqual(runtime, NAMED_COMBINATION, 'T03 named combination');
  artifact = await serveArtifact();
});

after(async () => {
  await browser?.close();
  await (await scrollbarBrowser)?.close();
  await artifact?.close();
});

function launch(scrollbars: ScrollbarMode): Promise<Browser> {
  const executable = process.env[EXECUTABLE_ENV];
  return chromium.launch({
    headless: true,
    ...(executable ? { executablePath: executable } : {}),
    ...(scrollbars === Scrollbars.visible ? { ignoreDefaultArgs: [HIDE_SCROLLBARS] } : {}),
  });
}

interface BrowserFixture {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  gameURL: string;
}
interface Artifacts {
  outputPath(file: string): string;
}

function npmVersion(): string {
  const npmResult =
    process.platform === 'win32'
      ? spawnSync('cmd.exe', ['/d', '/c', 'npm --version'], { encoding: 'utf8' })
      : spawnSync('npm', ['--version'], { encoding: 'utf8' });
  assert.equal(npmResult.status, 0, 'T03 npm version command');
  return npmResult.stdout.trim();
}

export function test(
  name: string,
  body: (fixture: BrowserFixture, artifacts: Artifacts) => Promise<void>,
  options: BrowserContextOptions = {},
  scrollbars: ScrollbarMode = Scrollbars.hidden,
import { decodeSnapshot } from '../snapshot.ts';
import { isWon } from '../game.ts';
import {
  createTournament,
  normalizeNames,
  recordScore,
  roundSize,
  isValidCode,
  isValidScore,
} from './rules.ts';
import type { TournamentData } from './rules.ts';

function object(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function extra(value: Record<string, unknown>, keys: string[]): string | null {
  return Object.keys(value).find((key) => !keys.includes(key)) ?? null;
}
function stable(_key: string, value: unknown): unknown {
  if (!object(value)) return value;
  return Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)));
}
export function exportTournament(t: TournamentData): string {
  return JSON.stringify({ format: 'neon-pairs/tournament', version: 1, ...t }, stable, 2);
}
export function readTournament(text: string): { data: TournamentData | null; error: string } {
  const invalid = { data: null, error: 'Invalid tournament.' };
  if (new TextEncoder().encode(text).length > 65536) return invalid;
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return invalid;
  }
  if (!object(raw)) return invalid;
  let unknown = extra(raw, [
    'format',
    'version',
    'players',
    'matches',
    'index',
    'phase',
    'snapshot',
  ]);
  if (unknown) return { data: null, error: `Unknown field: ${unknown}.` };
  if (
    raw.format !== 'neon-pairs/tournament' ||
    raw.version !== 1 ||
    !Array.isArray(raw.players) ||
    ![4, 8].includes(raw.players.length) ||
    !raw.players.every((p) => typeof p === 'string')
  )
    return invalid;
  const players = raw.players.filter((p): p is string => typeof p === 'string');
  const names = normalizeNames(players);
  if (names.error || names.names.some((n, i) => n !== players[i])) return invalid;
  if (
    !Array.isArray(raw.matches) ||
    raw.matches.length !== names.names.length - 1 ||
    typeof raw.index !== 'number' ||
    !Number.isInteger(raw.index) ||
    raw.index < 0 ||
    raw.index >= raw.matches.length
  )
    return invalid;
  const codes: string[] = [];
  for (let i = 0; i < raw.matches.length; i++) {
    const m: unknown = raw.matches[i];
    if (!object(m)) return invalid;
    unknown = extra(m, ['boardCode', 'players', 'scores', 'winner']);
    if (unknown) return { data: null, error: `Unknown field: ${unknown}.` };
    if (
      !isValidCode(m.boardCode, roundSize(names.names.length, i)) ||
      !Array.isArray(m.players) ||
      m.players.length !== 2 ||
      !Array.isArray(m.scores) ||
      m.scores.length !== 2
    )
      return invalid;
    codes.push(m.boardCode);
    for (const score of m.scores) {
      if (object(score)) {
        unknown = extra(score, ['moves', 'elapsedMs']);
        if (unknown) return { data: null, error: `Unknown field: ${unknown}.` };
      }
      if (score !== null && !isValidScore(score, roundSize(names.names.length, i))) return invalid;
    }
  }
  if (new Set(codes).size !== codes.length) return invalid;
  const phase = raw.phase;
  if (
    phase !== 'ready' &&
    phase !== 'playing' &&
    phase !== 'turnDone' &&
    phase !== 'matchDone' &&
    phase !== 'complete'
  )
    return invalid;
  const index = raw.index;
  let expected = createTournament(names.names, codes);
  for (let i = 0; i <= index; i++) {
    const source: unknown = raw.matches[i];
    if (!object(source) || !Array.isArray(source.scores)) return invalid;
    const required =
      i < index
        ? 2
        : phase === 'complete' || phase === 'matchDone'
          ? 2
          : phase === 'turnDone'
            ? 1
            : source.scores[0] !== null
              ? 1
              : 0;
    for (let n = 0; n < required; n++) {
      const score = source.scores[n];
      if (!isValidScore(score, roundSize(names.names.length, i))) return invalid;
      expected = recordScore({ ...expected, index: i }, score);
    }
  }
  if (
    (phase === 'complete' && raw.index !== raw.matches.length - 1) ||
    (phase === 'matchDone' && raw.index === raw.matches.length - 1)
  )
    return invalid;
  if (JSON.stringify(expected.matches, stable) !== JSON.stringify(raw.matches, stable))
    return invalid;
  if (raw.snapshot !== null && typeof raw.snapshot !== 'string') return invalid;
  if (raw.snapshot !== null) {
    if (phase !== 'playing') return invalid;
    const game = decodeSnapshot(raw.snapshot);
    if (!game || isWon(game) || game.boardCode !== codes[index]) return invalid;
  }
  return { data: { ...expected, index: index, phase, snapshot: raw.snapshot }, error: '' };
}

